int fact(int n) {
    if (n <= 1) return 1;
    return n * fact(n - 1);   // po powrocie zostaje mnożenie
}

int fact(int n, int acc) {
    if (n <= 1) return acc;
    return fact(n - 1, n * acc);   // wynik wywołania jest wynikiem funkcji
}

int fact(int n, int acc) {
    while (n > 1) { acc = n * acc; n = n - 1; }
    return acc;
}

